struct PackItem {
    let name: String
    let grams: Int
    let packed: Bool
}
let items = [PackItem(name: "Ботинки", grams: 900, packed: false),
             PackItem(name: "Зарядка", grams: 120, packed: false),
             PackItem(name: "Куртка", grams: 700, packed: true)]
var heavyLeft: [String] = []
for item in items {
    if !item.packed && item.grams >= 500 {
        heavyLeft.append(item.name.uppercased())
    }
}
var allPacked = true
for item in items where !item.packed { allPacked = false }

key:
let heavyLeft = items
    .filter { !$0.packed && $0.grams >= 500 }
    .map { $0.name.uppercased() }
let allPacked = items.allSatisfy { $0.packed }
print(heavyLeft, allPacked)

filter отвечает «какие вещи оставить», map — «что показать». Сначала фильтр, потом map: заглавные строки строим только для нужных вещей. allSatisfy даёт true, только если условие верно для всех элементов, а на пустом списке — true: упаковывать нечего. Вывод: ["БОТИНКИ"] false.

